import SideBar from "./components/sidebar.js";
import MiddleSection from "./components/middlesection.js";
import RightSection from "./components/rightsection.js";

import React, { useState } from "react";
import "./css/index.css";
import { BrowserRouter } from "react-router-dom";

function App() {
  const [articles, setArticles] = useState([]); // Store all articles
  const [selectedArticle, setSelectedArticle] = useState(null); // Track selected article
  const [openM, setOpenM] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [darkMode, setDarkMode] = useState(false); // Add darkMode state

  return (
    <React.StrictMode>
      <BrowserRouter>
        <SideBar 
          openM={openM} 
          setOpenM={setOpenM} 
          articles={articles} 
          setSearchQuery={setSearchQuery} // Ensure this is here
          darkMode={darkMode}
          setDarkMode={setDarkMode}
        />
        <MiddleSection
          articles={articles} 
          setArticles={setArticles} 
          selectedArticle={selectedArticle} 
          setSelectedArticle={setSelectedArticle}
          searchQuery={searchQuery}
          setSearchQuery={setSearchQuery}
          darkMode={darkMode}
          setDarkMode={setDarkMode}
        />
        <RightSection 
          openM={openM} 
          setOpenM={setOpenM} 
          setArticles={setArticles} 
          selectedArticle={selectedArticle}
          setSearchQuery={setSearchQuery}
          articles={articles}
          darkMode={darkMode}
          setDarkMode={setDarkMode} // Add this prop
        />
      </BrowserRouter>
    </React.StrictMode>
  );
}

export default App;