"use client";
import { useEffect } from "react";
import { motion, stagger, useAnimate } from "framer-motion";
import { cn } from "../../lib/utils";

export const TextGenerateEffect = ({
  words,
  className,
  filter = true,
  duration = 0.7,
  initialDelay = 0.7,
  darkMode = false, // ADD THIS PROP
}) => {
  const [scope, animate] = useAnimate();
  const wordsArray = words.split(" ");

  useEffect(() => {
    if (!scope.current) return;

    const startAnimation = () => {
      animate(
        "span",
        {
          opacity: 1,
          filter: filter ? "blur(0px)" : "none",
        },
        {
          duration: duration || 1,
          delay: stagger(0.2),
        }
      );
    };

    const timer = setTimeout(startAnimation, initialDelay * 1000);

    return () => clearTimeout(timer);
  }, [animate, filter, duration, initialDelay]);

  const renderWords = () => (
    <motion.div ref={scope}>
      {wordsArray.map((word, idx) => (
        <motion.span
          key={word + idx}
          className={`opacity-0 ${darkMode ? 'text-white' : 'text-black'}`} // FIXED: Dynamic text color
          style={{
            filter: filter ? "blur(10px)" : "none",
          }}
        >
          {word}{" "}
        </motion.span>
      ))}
    </motion.div>
  );

  return (
    <div className={className}>
      <div className="mt-4">
        <div className={`text-2xl leading-snug tracking-wide transition-colors duration-300 ${darkMode ? 'text-white' : 'text-black'}`}> {/* FIXED: Dynamic text color */}
          {renderWords()}
        </div>
      </div>
    </div>
  );
};