import React, { useEffect, useState } from "react";
import image from "../images/logo.png";
import { fetchData } from "../lib/api";
import { Toaster, toast } from "react-hot-toast";
import { Modal, Backdrop, Box } from '@mui/material';
import Fade from "@mui/material/Fade";
import { motion, AnimatePresence } from "framer-motion";

const modalStyle = {
  position: "absolute",
  top: "50%",
  left: "50%",
  transform: "translate(-50%, -50%)",
  width: "90%",
  maxWidth: "500px",
  bgcolor: "rgba(15, 23, 42, 0.95)",
  backdropFilter: "blur(20px)",
  borderRadius: "24px",
  boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.5)",
  border: "1px solid rgba(255, 255, 255, 0.1)",
  p: 0,
  overflow: "hidden"
};

// Added setSearchQuery to props to connect with MiddleSection filtering
function SideBar({ openM, setOpenM, articles = [], setSearchQuery }) {
  const [error, setError] = useState(null);
  const [feeds, setFeeds] = useState([
    { id: 1, name: "All links", count: 0, icon: "📥", type: "default" },
    { id: 2, name: "Starred", count: 0, icon: "⭐", type: "default" },
  ]);
  
  const [addFeedModal, setAddFeedModal] = useState(false);
  const [manageFeedsModal, setManageFeedsModal] = useState(false);
  const [deleteConfirmModal, setDeleteConfirmModal] = useState(false);
  const [newFeedUrl, setNewFeedUrl] = useState("");
  const [isAddingFeed, setIsAddingFeed] = useState(false);
  const [allFeeds, setAllFeeds] = useState({});
  const [isLoadingFeeds, setIsLoadingFeeds] = useState(false);
  const [feedToDelete, setFeedToDelete] = useState({ domain: null, feedUrl: null });
  const [activeFeed, setActiveFeed] = useState(1);

  const calculateSourceCounts = (articles) => {
    const sourceCounts = {};
    articles.forEach(article => {
      const source = article.author || article.source || 'Unknown';
      sourceCounts[source] = (sourceCounts[source] || 0) + 1;
    });
    return sourceCounts;
  };

  useEffect(() => {
    const loadData = async () => {
      try {
        const response = await fetchData("http://127.0.0.1:5000/json-keys");
        const sourceCounts = calculateSourceCounts(articles);
        
        // Map and then sort items from most articles to least
        const dynamicItems = response.feeds
          .map((item, index) => ({
            id: index + 3,
            name: item.name,
            count: sourceCounts[item.name] || 0,
            icon: item.icon,
            type: "feed"
          }))
          .sort((a, b) => b.count - a.count);

        setFeeds([
          { id: 1, name: "All links", count: articles.length, icon: "📥", type: "default" },
          { id: 2, name: "Starred", count: 0, icon: "⭐", type: "default" },
          { section: "Daily", items: dynamicItems },
        ]);
      } catch (error) {
        setError(error.message);
      }
    };
    loadData();
  }, [articles]);

  // Handle clicking a feed to trigger filtering in MiddleSection
  const handleFeedClick = (item) => {
  setActiveFeed(item.id);
  // We no longer call setSearchQuery(item.name) here
  };

  const loadAllFeeds = async () => {
    setIsLoadingFeeds(true);
    try {
      const response = await fetch("http://127.0.0.1:5000/list-feeds");
      const result = await response.json();
      if (result.success) {
        setAllFeeds(result.feeds);
      }
    } catch (error) {
      toast.error("Failed to load feeds");
    } finally {
      setIsLoadingFeeds(false);
    }
  };

  const handleAddFeed = async () => {
    if (!newFeedUrl.trim()) return toast.error("Please enter a website URL");
    setIsAddingFeed(true);
    try {
      const response = await fetch("http://127.0.0.1:5000/add-rss-feed", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: newFeedUrl }),
      });
      const result = await response.json();
      if (result.success) {
        toast.success(result.message);
        setAddFeedModal(false);
        setNewFeedUrl("");
      }
    } finally {
      setIsAddingFeed(false);
    }
  };

  const handleDeleteFeed = async () => {
    const { domain, feedUrl } = feedToDelete;
    try {
      let url = `http://127.0.0.1:5000/delete-feed?domain=${encodeURIComponent(domain)}`;
      if (feedUrl) url += `&feed_url=${encodeURIComponent(feedUrl)}`;
      const response = await fetch(url, { method: "DELETE" });
      const result = await response.json();
      if (result.success) {
        toast.success(result.message);
        loadAllFeeds();
      }
    } finally {
      setDeleteConfirmModal(false);
    }
  };

  return (
    <>
      <style>{`
        .hide-scrollbar::-webkit-scrollbar { display: none; }
        .hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
      
      <Toaster />
      
      <motion.div initial={{ x: -260 }} animate={{ x: 0 }} className="relative w-64 h-screen bg-[#05070a] border-r border-white/5 flex flex-col overflow-hidden">
        <div className="absolute inset-0 opacity-20 pointer-events-none">
          <motion.svg animate={{ y: [0, -15, 0], x: [-10, 10, -10] }} transition={{ duration: 8, repeat: Infinity, ease: "easeInOut" }} className="absolute bottom-0 w-[200%] h-64 text-blue-500/30 fill-current" viewBox="0 0 1440 320">
            <path d="M0,160L48,176C96,192,192,224,288,213.3C384,203,480,149,576,144C672,139,768,181,864,181.3C960,181,1056,139,1152,122.7C1248,107,1344,117,1392,122.7L1440,128L1440,320L1392,320C1344,320,1248,320,1152,320C1056,320,960,320,864,320C768,320,672,320,576,320C480,320,384,320,288,320C192,320,96,320,48,320L0,320Z"></path>
          </motion.svg>
        </div>

        <div className="relative z-10 flex flex-col h-full backdrop-blur-3xl bg-black/40">
          <div className="pt-5 pb-6 px-6 flex flex-col items-center">
            <img src={image} className="h-30 w-auto invert opacity-80" alt="Logo" />
            <div className="flex items-center justify-between w-full bg-white/5 p-1 rounded-2xl border border-white/10 backdrop-blur-md">
              <button onClick={() => { loadAllFeeds(); setManageFeedsModal(true); }} className="flex-1 py-2 hover:bg-white/10 rounded-xl transition-all text-sm flex justify-center">⚙️</button>
              <div className="w-[1px] h-4 bg-white/10" />
              <button onClick={() => setAddFeedModal(true)} className="flex-[1.5] py-2 hover:bg-blue-500/20 rounded-xl text-blue-400 font-bold text-[10px] tracking-widest flex items-center justify-center gap-1"><span>+</span> FEED</button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto px-4 hide-scrollbar list space-y-6 pb-10">
            {feeds.map((item, idx) => (
              <div key={idx}>
                {item.section ? (
                  <div className="mt-4">
                    <p className="px-2 mb-2 text-[10px] font-bold text-white/20 uppercase tracking-[0.2em]">{item.section}</p>
                    {item.items?.map(sub => (
                      <FeedItem key={sub.id} item={sub} isActive={activeFeed === sub.id} onClick={() => handleFeedClick(sub)} />
                    ))}
                  </div>
                ) : (
                  <FeedItem item={item} isActive={activeFeed === item.id} onClick={() => handleFeedClick(item)} />
                )}
              </div>
            ))}
          </div>
        </div>
      </motion.div>

      {/* Modals for Manage, Add, and Delete remain unchanged */}
      <Modal open={manageFeedsModal} onClose={() => setManageFeedsModal(false)} closeAfterTransition BackdropComponent={Backdrop} BackdropProps={{ timeout: 500 }}>
        <Fade in={manageFeedsModal}>
          <Box sx={modalStyle}>
            <div className="p-6">
              <h2 className="text-xl font-bold mb-6 text-white">Your Feeds</h2>
              <div className="max-h-[300px] overflow-y-auto hide-scrollbar space-y-3">
                {isLoadingFeeds ? <p className="text-white/50 text-center">Loading...</p> : 
                  Object.entries(allFeeds).map(([domain, urls]) => (
                    <div key={domain} className="bg-white/5 p-3 rounded-xl border border-white/5">
                      <p className="text-xs font-bold text-blue-400 mb-2 uppercase">{domain}</p>
                      {urls.map((u, i) => (
                        <div key={i} className="flex justify-between items-center text-[11px] text-white/60 py-1">
                          <span className="truncate mr-4">{u}</span>
                          <button onClick={() => { setFeedToDelete({domain, feedUrl: u}); setDeleteConfirmModal(true); }} className="text-red-400">Remove</button>
                        </div>
                      ))}
                    </div>
                  ))
                }
              </div>
            </div>
          </Box>
        </Fade>
      </Modal>

      <Modal open={addFeedModal} onClose={() => setAddFeedModal(false)}>
        <Box sx={modalStyle}>
          <div className="p-8">
            <h2 className="text-xl font-bold text-white mb-6">Add New Feed</h2>
            <input type="text" value={newFeedUrl} onChange={(e) => setNewFeedUrl(e.target.value)} placeholder="https://example.com" className="w-full p-4 bg-white/5 border border-white/10 rounded-2xl text-white mb-6 outline-none focus:border-blue-500 transition-all" />
            <button onClick={handleAddFeed} disabled={isAddingFeed} className="w-full py-4 bg-blue-600 text-white rounded-2xl font-bold hover:bg-blue-500 transition-all">{isAddingFeed ? "Detecting..." : "Add to Library"}</button>
          </div>
        </Box>
      </Modal>

      <Modal open={deleteConfirmModal} onClose={() => setDeleteConfirmModal(false)}>
        <Box sx={modalStyle}>
          <div className="p-8 text-center">
            <h2 className="text-white font-bold mb-4">Delete Feed?</h2>
            <p className="text-white/50 text-sm mb-8">This action cannot be undone.</p>
            <div className="flex gap-4">
              <button onClick={() => setDeleteConfirmModal(false)} className="flex-1 py-3 text-white/50">Cancel</button>
              <button onClick={handleDeleteFeed} className="flex-1 py-3 bg-red-500/20 text-red-500 rounded-xl font-bold">Delete</button>
            </div>
          </div>
        </Box>
      </Modal>
    </>
  );
}

const FeedItem = ({ item, isActive, onClick }) => (
  <motion.div
    whileTap={{ scale: 1.5 }}
    onClick={onClick}
    className={`flex items-center justify-between px-1 py-1 rounded-2xl cursor-pointer transition-all mb-1 ${
      isActive ? 'bg-blue-500/10 text-white border border-blue-500/20' : 'text-white/50 hover:bg-white/5'
    }`}
  >
    <div className="flex items-center gap-3">
      <span className="text-lg">{item.icon}</span>
      <span className={`text-l tracking-tight ${isActive ? 'font-bold' : 'font-medium'}`}>{item.name}</span>
    </div>
    {item.count !== undefined && (
      <span className={`text-[10px] px-2 py-0.5 rounded-lg ${isActive ? 'bg-blue-500 text-white' : 'bg-white/5 text-white/30'}`}>
        {item.count}
      </span>
    )}
  </motion.div>
);

export default SideBar;